    <div class="fld"><label>Пространства и базы</label>${['Регламенты','ПТО','Личные заметки юристов'].map((s,i)=>`<label class="row" style="gap:8px;align-items:center"><input type="checkbox" class="chk" ${i<2?'checked':''}>${s}</label>`).join('')}</div>
