  page(a.name,STAND.seg([['src','Источники'],['pr','Промпт'],['log','Журнал']],t,'agt')+body,{icon:'shine',after:sc(a.on?'включён':'выключен')+' '+kc('промпт v'+a.v,'lav'),extra:`<button class="btn" id="agsave">Сохранить</button>`});
